// Der Endpunkt antwortet bewusst mit HTTP 200, auch wenn eine einzelne
// Quelle nicht erreichbar war — eine kaputte Quelle soll die anderen drei
// nicht mitreissen. Ohne diese Pruefung stuende die Ausfuehrung in n8n
// deshalb auf gruen, waehrend z.B. die IBJJF seit Tagen nichts liefert.
// Hier wird daraus ein echter Fehlschlag, den man in der Liste sieht.

const r = $input.first().json;
const probleme = [];

if (r.error) {
  probleme.push(`Lauf abgelehnt: ${r.error}${r.detail ? ` — ${r.detail}` : ''}${r.hint ? ` (${r.hint})` : ''}`);
}

for (const s of r.sources ?? []) {
  if (s.error) probleme.push(`${s.source}: Quelle nicht erreichbar — ${s.error}`);
  if (s.insertError) probleme.push(`${s.source}: Anlegen fehlgeschlagen — ${s.insertError}`);
  for (const e of s.updateErrors ?? []) probleme.push(`${s.source}: Aendern fehlgeschlagen — ${e}`);
}

if (probleme.length > 0) {
  throw new Error(probleme.join('\n'));
}

// Eine Zeile je Quelle, damit in der Ausfuehrungsliste auf einen Blick steht,
// was der Lauf getan hat.
return (r.sources ?? []).map((s) => ({
  json: {
    quelle: s.source,
    gefunden: s.found,
    neu: s.inserts,
    geaendert: s.updates,
    unveraendert: s.unchanged,
    hinweise: (s.notes ?? []).length,
    gefiltert: s.filtered ?? [],
  },
}));
